using Newtonsoft.Json;
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using System.Xml;
using System.Text;
using System.Text.Json;
namespace ToolTaiHD
{
    public class SvgCaptchaSolver

    {
        private string model = "";

        public string SolveCaptcha(string svgCaptchaFile)
        {
            string svgCaptcha = File.ReadAllText(svgCaptchaFile);

            byte[] modelBytes = Convert.FromBase64String(model);
            string modelJson = Encoding.UTF8.GetString(modelBytes);
            var parsedModel = System.Text.Json.JsonSerializer.Deserialize<Dictionary<string, string>>(modelJson);

            // hoặc

            XmlDocument doc = new XmlDocument();
            doc.LoadXml(svgCaptcha);

            var paths = doc.GetElementsByTagName("path");
            List<XmlElement> noStrokePaths = new List<XmlElement>();

            foreach (XmlElement path in paths)
            {
                if (!path.HasAttribute("stroke") || string.IsNullOrEmpty(path.GetAttribute("stroke")))
                {
                    noStrokePaths.Add(path);
                }
            }

            List<int> vals = new List<int>();
            foreach (var path in noStrokePaths)
            {
                string d = path.GetAttribute("d");
                string firstPart = d.Split('.')[0].Replace("M", "");
                if (int.TryParse(firstPart, out int val))
                {
                    vals.Add(val);
                }
            }

            List<int> sortedVals = vals.OrderBy(x => x).ToList();
            string[] solution = new string[6];

            for (int i = 0; i < noStrokePaths.Count; i++)
            {
                string pattern = Regex.Replace(noStrokePaths[i].GetAttribute("d"), @"[\d.\s]*", "");
                int index = sortedVals.IndexOf(vals[i]);
                if (index < solution.Length && parsedModel.ContainsKey(pattern))
                {
                    solution[index] = parsedModel[pattern];
                }
            }

            return string.Join("", solution);
        }
    }
}
